function validate(input) {
  const [nums] = input;
  if (!Array.isArray(nums)) return 'nums must be a JSON array.';
  if (nums.length > 1000) return 'nums has at most 1000 elements.';
  if (JSON.stringify(nums).length > 20000) return 'Keep nums under 20,000 characters of JSON.';
  return null;
}

