function adapt(input, solve, kit) {
  const [nums] = input;
  if (typeof nums.last !== 'function') throw new Error('Arrays have no last method yet: assign a function to Array.prototype.last.');
  const before = JSON.stringify(nums);
  const value = nums.last();
  if (value === undefined) throw new Error('last() returned undefined; it should return the last element, or -1 for an empty array.');
  if (JSON.stringify(nums) !== before) throw new Error('last() must not change the array.');
  kit.trace(`nums.last() returns ${JSON.stringify(value)}`);
  return value;
}

