function generate(rand, size) {
  const value = (depth) => {
    const roll = rand();
    if (roll < 0.35) return Math.floor(rand() * 21) - 10;
    if (roll < 0.5) return ['', 'a', 'last', '-1', 'null'][Math.floor(rand() * 5)];
    if (roll < 0.6) return rand() < 0.5;
    if (roll < 0.7) return null;
    if (depth > 1) return 0;
    if (roll < 0.85) return Array.from({ length: Math.floor(rand() * 3) }, () => value(depth + 1));
    return { key: value(depth + 1) };
  };
  const length = size === 'small' ? Math.floor(rand() * 5) : 1000;
  return [Array.from({ length }, () => value(0))];
}
